using Riok.Mapperly.Abstractions;
using Pleiades.Playground.Events.Api.DataAccessObjects;
using Pleiades.Playground.Events.Api.DataTransferObjects;
using Pleiades.Playground.Events.DataTransferObjects;
using Pleiades.Playground.Notification.DataTransferObjects;

namespace Pleiades.Playground.Events.Api.Mapping;

/// <summary>
/// Source-generated mapper (Riok.Mapperly) between DAOs and DTOs.
/// Nested members (the TimeBucket distribution) and the reverse of one-directional element mappings
/// are generated by Mapperly automatically; only the invoked entry points are declared here.
/// </summary>
[Mapper]
internal static partial class EventsMapper
{
    // NotificationEvent
    public static partial NotificationEventDtoV1 Map(NotificationEventDao source);
    public static partial NotificationEventDao Map(NotificationEventDtoV1 source);
    public static partial List<NotificationEventDtoV1> Map(List<NotificationEventDao> source);
    public static partial List<NotificationEventDao> Map(List<NotificationEventDtoV1> source);

    // PairedNotificationEvent, LevelDistribution, TimeBucket (DAO -> DTO only)
    public static partial PairedNotificationEventDtoV1 Map(PairedNotificationEventDao source);
    public static partial List<PairedNotificationEventDtoV1> Map(List<PairedNotificationEventDao> source);
    public static partial LevelDistributionDtoV1 Map(LevelDistributionDao source);
    public static partial List<LevelDistributionDtoV1> Map(List<LevelDistributionDao> source);
    public static partial TimeBucketDtoV1 Map(TimeBucketDao source);
    public static partial List<TimeBucketDtoV1> Map(List<TimeBucketDao> source);

    // NotificationMessageStatistics (DAO -> DTO only): rename tick fields and convert long ticks to TimeSpan
    [MapProperty(nameof(NotificationMessageStatisticsDao.TotalDurationTicks), nameof(NotificationMessageStatisticsDtoV1.TotalDuration), Use = nameof(TicksToTimeSpan))]
    [MapProperty(nameof(NotificationMessageStatisticsDao.AverageDurationTicks), nameof(NotificationMessageStatisticsDtoV1.AverageDuration), Use = nameof(TicksToTimeSpan))]
    public static partial NotificationMessageStatisticsDtoV1 Map(NotificationMessageStatisticsDao source);
    public static partial List<NotificationMessageStatisticsDtoV1> Map(List<NotificationMessageStatisticsDao> source);

    private static TimeSpan TicksToTimeSpan(long ticks) => TimeSpan.FromTicks(ticks);
}
